import { useEffect, useState } from "react";
import Loader from "react-loaders";              // ⬅️ ADD THIS
import "./index.scss";
import AnimatedLetters from "../../AnimatedLetters";
import useInView from "../../../hooks/useInView";



const About = () => {
  const [letterClass, setLetterClass] = useState("text-animate");
  const [ref, inView] = useInView();

  useEffect(() => {
    const timer = setTimeout(() => {
      setLetterClass("text-animate-hover");
    }, 3000);

    return () => clearTimeout(timer);
  }, []);

  return (
    <>
      <div
        id="about"
        ref={ref}
        className={`container about-page fade-section ${
          inView ? "in-view" : ""
        }`}
      >
        <div className="text-zone">
          <h1 className="page-title">
            <AnimatedLetters
              letterClass={letterClass}
              strArray={"About Me:".split("")}
              index={15}
            />
          </h1>

          <p className="intro">
            I'm Chris, a full-stack web developer based in New York City who
            enjoys turning messy, real-world problems into clean, thoughtful web
            experiences.
          </p>

          <p>
            Most of my work centers around <span>React</span>,{" "}
            <span>Next.js</span>, and <span>TypeScript</span>—building data-
            driven tools like fantasy sports optimizers, smarter fitness
            tracking, and utilities for the Pokémon TCG. I care a lot about
            clear UX, performance, and code that’s easy for the next developer
            to understand.
          </p>

          <p>
            Right now I'm focused on sharpening my back-end skills with{" "}
            <span>Node</span>, <span>APIs</span>, and <span>MongoDB</span>, and
            growing into a role where I can ship production features, learn from
            more senior engineers, and contribute to a strong engineering
            culture.
          </p>

          <div className="about-grid">
            <div className="about-card">
              <h2>What I&apos;m focused on</h2>
              <ul>
                <li>Shipping small, end-to-end features in real projects</li>
                <li>Deepening my TypeScript and testing habits</li>
                <li>Designing clean, predictable API contracts</li>
                <li>
                  Leveling up in performance, accessibility, and DX (developer
                  experience)
                </li>
              </ul>
            </div>

            <div className="about-card">
              <h2>Tools I reach for</h2>
              <div className="pill-row">
                <span className="pill">React</span>
                <span className="pill">Next.js</span>
                <span className="pill">TypeScript</span>
                <span className="pill">JavaScript</span>
                <span className="pill">Node.js</span>
                <span className="pill">MongoDB</span>
                <span className="pill">CSS / SCSS</span>
                <span className="pill">REST APIs</span>
              </div>
            </div>
          </div>

          <p className="closing">
            Outside of coding, you&apos;ll usually find me playing or testing
            Pokémon TCG decks, lifting, or drilling chess positions—anything
            that mixes strategy, iteration, and long-term improvement.
          </p>
        </div>
      </div>

      <Loader type="pacman" />
    </>
  );
};

export default About;
